viz.option:
option = {
  title: {
    text: 'CPU Utilisation',
    left: 'center'
  },
  tooltip: {
    formatter: '{a}: {c}%'
  },
  series: [
    {
      name: 'CPU',
      type: 'gauge',
      min: 0,
      max: 100,
      splitNumber: 10,
      axisLine: {
        lineStyle: {
          width: 20,
          color: [
            [0.6,  '#5cb85c'],
            [0.85, '#f0ad4e'],
            [1,    '#d9534f']
          ]
        }
      },
      pointer: {
        itemStyle: {
          color: 'auto'
        }
      },
      axisTick: {
        distance: -25,
        length: 8,
        lineStyle: { color: '#fff', width: 2 }
      },
      splitLine: {
        distance: -30,
        length: 20,
        lineStyle: { color: '#fff', width: 4 }
      },
      axisLabel: {
        color: 'inherit',
        distance: 35,
        fontSize: 12
      },
      detail: {
        valueAnimation: true,
        formatter: '{value}%',
        color: 'inherit',
        fontSize: 22
      },
      data: [
        { value: 73.4, name: 'CPU %' }
      ]
    }
  ]
};

pre.code:
data: [
  { value: 73, name: 'CPU' },
  { value: 58, name: 'Memory' },
  { value: 41, name: 'Disk' }
]

viz.option:
option = {
  title: {
    text: 'System Resources',
    left: 'center'
  },
  tooltip: {
    formatter: '{b}: {c}%'
  },
  series: [
    {
      type: 'gauge',
      min: 0,
      max: 100,
      splitNumber: 5,
      radius: '80%',
      axisLine: {
        lineStyle: {
          width: 15,
          color: [
            [0.6,  '#5cb85c'],
            [0.85, '#f0ad4e'],
            [1,    '#d9534f']
          ]
        }
      },
      splitLine: {
        distance: -18,
        length: 15,
        lineStyle: { color: '#fff', width: 3 }
      },
      axisTick: {
        distance: -12,
        length: 8,
        lineStyle: { color: '#fff', width: 2 }
      },
      axisLabel: {
        distance: 20,
        fontSize: 11,
        color: '#555'
      },
      anchor: {
        show: true,
        showAbove: true,
        size: 18,
        itemStyle: { borderWidth: 8 }
      },
      detail: {
        valueAnimation: true,
        formatter: '{value}%',
        fontSize: 14,
        offsetCenter: [0, '70%']
      },
      data: [
        { value: 73, name: 'CPU' },
        { value: 58, name: 'Memory' },
        { value: 41, name: 'Disk' }
      ]
    }
  ]
};

